cat > rot13.py <<'EOF'
import sys
out = []
for ch in sys.stdin.read():
    if 'a' <= ch <= 'z':
        out.append(chr((ord(ch) - 97 + 13) % 26 + 97))
    elif 'A' <= ch <= 'Z':
        out.append(chr((ord(ch) - 65 + 13) % 26 + 65))
    else:
        out.append(ch)
sys.stdout.write(''.join(out))
EOF
